#define MAT_SPHERE 2.0
#define MAT_BG 1.0
#define MAT_PLANE 3.0
#define MAT_CLASP 4.
#define MAT_PAGES 5.
#define MAT_COVERS 6.


#define MAT_LIGHT -10.0

#define EPS 0.0001
#define PI 3.14159

#define MRX(X) mat3(1., 0., 0. ,0., cos(X), -sin(X) ,0., sin(X), cos(X))	//x axis rotation matrix
#define MRY(X) mat3(cos(X), 0., sin(X),0., 1., 0.,-sin(X), 0., cos(X))	//y axis rotation matrix	
#define MRZ(X) mat3(cos(X), -sin(X), 0.	,sin(X), cos(X), 0.	,0., 0., 1.)	//z axis rotation matrix
#define COMBINE(MAT1, MAT2) MAT1.x >= -0.001 && MAT1.x <= MAT2.x ? MAT1 : MAT2
#define LIGHT_POS vec3(-1., 3., 1.) // position of the light
#define BULB_SIZE 0.05 // size of the physical bulb

#define ANTIALIASING_SAMPLES 4 //4 is max.

#define BG_DISTANCE 20.

const vec3 eps = vec3(EPS, 0., 0.);

const vec3 MATERIAL_MAP[14] = vec3[14](
    vec3(0.1, 0.1, 0.1) /*albedo*/, vec3(0.1, 0.1, 0.1), // light
    vec3(0.3, 0.4, 0.4) /*albedo*/, vec3(0.05 /*roughness*/, 0.4/*Fo*/, 0. /*dummy*/ ), //MAT_BOX
    vec3(0.5, 0.5, 0.3) /*albedo*/, vec3(0.2 /*roughness*/, 0.05/*Fo*/, 0. /*dummy*/ ), //MAT_SPHERE
    vec3(0.2, 0.4, 0.4) /*albedo*/, vec3(0.1 /*roughness*/, 0.05/*Fo*/, 0. /*dummy*/ ), //MAT_PLANE
    vec3(0.63, 0.61, 0.58) /*albedo*/, vec3(0.03 /*roughness*/, 0.5/*Fo*/, 0. /*dummy*/ ), //MAT_CLASP
    vec3(0.5, 0.4, 0.4) /*albedo*/, vec3(0.2 /*roughness*/, 0.05/*Fo*/, 0. /*dummy*/ ), //MATERIAL_PAGES
    vec3(0.9, 0.6, 0.6) /*albedo*/, vec3(0.2 /*roughness*/, 0.05/*Fo*/, 0. /*dummy*/ )  //MATERIAL_COVERS

);

const vec3 JITTER[4] = vec3[4](
    vec3(0., 0., 0.), vec3(0., 1., 0.),
    vec3(0., 0., 1.), vec3(0., 1., 1.)
);

const float c_lightPower = 200.;
const vec3 c_lightColor = vec3(0.1);

vec2 SphereSDF(in vec3 point,in vec3 center,in float radius, in float material)
{
    return vec2(length(point - center) - radius, material);
}
vec2 PlaneSDF(in vec3 point, in vec3 planePosition, in vec3 planeNormal, in float material)
{
    return vec2(dot(point - planePosition, planeNormal), material);
}

vec2 BoxSDF(in vec3 point, in vec3 center, in vec3 sizes, in float material)
{
    vec3 vectorFromBoxCornerToPoint = abs(point - center) - sizes;
    float distanceIfPointOutsisdeBox = length(max(vectorFromBoxCornerToPoint, 0.));
    float distanceIfPointInsideBox = min(max(vectorFromBoxCornerToPoint.x, max(vectorFromBoxCornerToPoint.y, vectorFromBoxCornerToPoint.z)), 0.);
    return vec2(distanceIfPointOutsisdeBox + distanceIfPointInsideBox, material);
}

float Subtract( float d1, float d2 )
{
	return max(d1, -d2);
}

float CylinderSDF( vec3 p, vec3 origin, vec2 h )
{
    vec2 d = abs(vec2(length(p.xz + vec2(0., origin.z)),p.y)) - h;
    return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float sdCappedCylinder( vec3 p, vec3 origin, float h)
{
  vec2 d = abs(vec2(length(p.xz),p.y)) - vec2(h,h);
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float box( vec3 p, vec3 origin, vec3 b )
{
    vec3 d = abs(p + origin) - b;
    return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0));
}

vec2 BookSDF( vec3 p, vec3 b, in float excluded)
{
    vec3 inset = vec3(0.00,0.02,0.00);
    //float pageDistance = box(p, vec3(0.,0.,0.02), b-inset);

    float xCoord = p.x - 0.005*clamp(round(p.x/0.005),-19.,19.);

    vec2 pages = vec2(100000., -1);
    if(excluded != MAT_PAGES)
    {
        float pageDistance = box(vec3(xCoord, p.y, p.z), vec3(0.,0.,0.02), vec3(b.x*0.003, b.y, b.z) - inset);
        pages = vec2(pageDistance, MAT_PAGES);
    }

    vec3 boxThickness = b;
    float coverThick = 0.005;

    vec2 covers = vec2(100000., -1);
    if(excluded != MAT_COVERS)
    {
        vec3 coverSurfaceDistortion = vec3(coverThick, boxThickness.y, boxThickness.z);
        vec2 coverRight = BoxSDF(p, vec3(boxThickness.x - coverThick,0,0), coverSurfaceDistortion, MAT_COVERS);
        vec2 coverLeft = BoxSDF(p, vec3(-boxThickness.x + coverThick,0,0), coverSurfaceDistortion, MAT_COVERS);
        // book without spikes
        covers= COMBINE(coverRight, coverLeft);
    }

    pages = COMBINE(covers, pages);

	// the back cover of the book.
    float backCoverDistance = CylinderSDF(p, b, b.xy);
    backCoverDistance = Subtract(backCoverDistance, CylinderSDF(p, b, vec2(b.x - 2.*coverThick, b.y + 5.)));
    backCoverDistance = Subtract(backCoverDistance, box(p, vec3(0.,0.,0.), b + vec3(0.25, 0.25, 0.)));

    return COMBINE(pages, vec2(backCoverDistance, MAT_COVERS));
}


vec2 CoverSDF(vec3 p, vec3 boxSize)
{
    float scale = 20.;

    boxSize *= vec3(1.10, 0.25, 0.33333);    

    float c = 0.333;
    vec3 l = vec3(0., 1., 0.);
    p -= vec3(0., .0, -boxSize.z*scale/10.);
    vec3 claspPos = p - 0.333*clamp(round(p/c),-l,l);

    vec2 clasps = vec2(100000., -1);
    float coverThick = 0.005;
    {
        vec3 claspSurfaceDistortion = vec3(coverThick, boxSize.y, boxSize.z);
        vec2 claspRight = BoxSDF(claspPos, vec3(boxSize.x - coverThick,0,0), claspSurfaceDistortion, MAT_CLASP);
        vec2 claspLeft = BoxSDF(claspPos, vec3(-boxSize.x + coverThick,0,0), claspSurfaceDistortion, MAT_CLASP);
        // book without spikes
        clasps= COMBINE(claspRight, claspLeft);
    }

	// the back cover of the book.
    float backCoverDistance = CylinderSDF(claspPos, boxSize, boxSize.xy);
    backCoverDistance = Subtract(backCoverDistance, CylinderSDF(claspPos, boxSize, vec2(boxSize.x - 2.*coverThick, boxSize.y + 5.)));
    backCoverDistance = Subtract(backCoverDistance, box(claspPos, vec3(0.,0.,0.), boxSize + vec3(0.25, 0.25, 0.)));


    return COMBINE(clasps, vec2(backCoverDistance, MAT_CLASP));
}

vec2 Book(vec3 pos, in float excluded)
{
    pos *= 0.6;
    //pos.z += sin(pos.z*pos.x*10.)*0.01;
    pos.x += cos((pos.z)*10.)*0.01;
    pos.x += sin((pos.y)*10.)*0.005;


    vec2 spikes = vec2(100000., -1);
    if(excluded != MAT_CLASP)
        spikes = CoverSDF(pos, vec3(0.1, 0.5, 0.3));

    vec2 pages = COMBINE(spikes, BookSDF(pos, vec3(0.1, 0.5, 0.3), excluded));
    return pages;
}

vec2 Geometry(in vec3 point, in float excluded)
{
    vec2 sphere = vec2(10000., 0.);
    if (excluded != MAT_SPHERE)
    {
        vec3 center = vec3(-0.0, 0., 0.5);
        sphere = SphereSDF(point, center, .7, MAT_SPHERE);
    }

    //mat3 rotation = MRZ(PI/2.)*MRY(0.2);
    mat3 rotation = MRZ(-0.5);
    vec2 book = vec2(10000., 0.);
    vec3 bookPosition = vec3(-0.95, +0.1, -0.1);
    book = Book(rotation*(point - bookPosition), excluded);        //box = BoxSDF(MRX(0.2)*rotation*point, rotation*vec3(0.5, 0.3, 1.), vec3(0.3,0.4, 0.7));

    vec2 distToSurfaceAndMaterial = COMBINE(book, sphere);
    if (excluded != MAT_BG)
    {
        distToSurfaceAndMaterial = COMBINE(distToSurfaceAndMaterial, BoxSDF(MRY(0.5)*point, vec3(-0.5, -0.4, 1.5), vec3(0.5, 0.4, 0.1), MAT_BG));
    }

    if (excluded == 0.)
    {
        vec2 light = SphereSDF(point, LIGHT_POS, BULB_SIZE, MAT_LIGHT);
        distToSurfaceAndMaterial = COMBINE(distToSurfaceAndMaterial, light);
    }

    if (excluded != MAT_PLANE)
    {
        vec3 offset = vec3(0., cos(point.z*100. + cos(point.x*100.))*0.1 + sin(point.x*10. + point.z), 0.)*0.01;
        distToSurfaceAndMaterial = COMBINE(distToSurfaceAndMaterial, BoxSDF(point, vec3(0., -0.8, 0.), vec3(3., 0.1, 4.), MAT_PLANE) /*PlaneSDF(point, vec3(0., -0.7, 0.), normalize(vec3(0., 1., 0.)), MAT_PLANE)*/);
    }

    return distToSurfaceAndMaterial;

}

void Scene(vec3 viewOrigin, vec3 viewDirection, out float t, out float material, out vec3 surfaceNormal, in float excluded)
{
    t = 0.;
    const float MIN_STEP_SIZE = 0.001;
    for (int marchStep = 0; marchStep < 1000; marchStep++)
    {
        vec3 point = viewOrigin + viewDirection*t;
        vec2 distToSurfaceAndMaterial = Geometry(point, excluded);
        t = distToSurfaceAndMaterial.x + t;

        if (abs(distToSurfaceAndMaterial.x) < 0.00001)
        {
            material = distToSurfaceAndMaterial.y;
            surfaceNormal = normalize(vec3(Geometry(point + eps.xyy, excluded).x - Geometry(point - eps.xyy, excluded).x, 
                                Geometry(point + eps.yxy, excluded).x - Geometry(point - eps.yxy, excluded).x, 
                                Geometry(point + eps.yyx, excluded).x - Geometry(point - eps.yyx, excluded).x));
            break;
        }
        else if (t > 1000.)
        {
            break;
        }
    }

}

void GetDiffuseMaterial(in float materialIndex, in vec3 sufraceNormal, in vec3 surfacePosition, out vec3 albedo, out vec3 materialProperties)
{

    materialProperties = MATERIAL_MAP[int(materialIndex*2.) + 1];
    albedo = MATERIAL_MAP[int(materialIndex*2.)];
    if (materialIndex == MAT_PLANE)
    {
        albedo = texture(iChannel0, surfacePosition.xz*0.1).xyz;
    }
    else if (materialIndex == MAT_PAGES)
    {
        vec2 uvFunc  = vec2(sin(surfacePosition.y*200. + cos(surfacePosition.x*5.)), cos(surfacePosition.z*5.));
        albedo = texture(iChannel1, uvFunc+surfacePosition.xy).rgb*vec3(0.6, 1., 1.);
    }

}

vec3 Light(in vec3 surfacePosition, 
            in vec3 surfaceNormal, 
            in float surfaceMaterial, 
            in vec3 viewDirection)
{

    vec3 lightDirNotNormalized = surfacePosition - LIGHT_POS;
    vec3 lightDirNormalized = normalize(lightDirNotNormalized);
    vec3 halfVector = normalize(-lightDirNormalized - viewDirection);

    vec3 randomVec = normalize(vec3(
        fract(sin(dot(surfacePosition.xy, vec2(12.9898, 78.233))) * 43758.5453),
        fract(sin(dot(surfacePosition.yz, vec2(93.9898, 67.345))) * 29358.5453),
        fract(sin(dot(surfacePosition.zx, vec2(15.9898, 27.345))) * 15731.5453)
    ));

    // Getting Material properties.
    vec3 albedo, materialProperties;
    GetDiffuseMaterial(surfaceMaterial, surfaceNormal, surfacePosition, albedo, materialProperties);
    surfaceNormal = normalize(100.*randomVec*pow(materialProperties.x, 4.) + surfaceNormal);

    // There is a lot of division. We use eps for clamping to positive values to avoid divising by zero. 
    const float epsilon = 1e-5;
    float normalDotHalfVector = max(dot(halfVector, surfaceNormal), epsilon);
    float normalDotView = max(dot(surfaceNormal, -viewDirection), epsilon);
    float halfDotView = max(dot(halfVector, -viewDirection), epsilon);
    float normalDotLight = max(dot(surfaceNormal, -lightDirNormalized), epsilon);

    // Reflectance at normal incidence (Fresnel-Schlick approximation)
    float Fo = materialProperties.y; // Metallic reflectance A physical property:  0.04 for dielectrics and 0.5 for metallic.
    float Fresnel_Schlick = Fo + (1.0 - Fo) * pow(1.0 - normalDotView, 5.0); // Approximation of Fresnel term by Schlick.

    // GGX Distribution. This is essentially a probablity density funciton  for normals based on the roughness parameter.
    float materialRoughness = materialProperties.x;
    float roughnessSquared = materialRoughness * materialRoughness;
    float NdotH = max(dot(surfaceNormal, halfVector), 0.0);
    float GGXDistr = roughnessSquared / (PI * pow((NdotH * NdotH * (roughnessSquared - 1.0) + 1.0), 2.0));


    // Geometric attenuation term (Smith-Schlick GGX approximation)
    float GeometricAttenuation = min(1.0, min(2.0 * normalDotHalfVector * normalDotView / halfDotView, 
                                           2.0 * normalDotHalfVector * normalDotLight / halfDotView));

    // Specular term calculation
    float kSpec = Fresnel_Schlick * GeometricAttenuation * GGXDistr / (PI * normalDotView * normalDotLight);

    float incomingRadiance = (c_lightPower / (4.0 * PI * dot(lightDirNotNormalized, lightDirNotNormalized)));

    // Diffuse term calculation (Lambertian diffuse)
    vec3 diffuseLighting = (1. - Fresnel_Schlick)*albedo * max(0.0, normalDotLight)*incomingRadiance;


    // Final color output
    vec3 specularColor = kSpec * c_lightColor*incomingRadiance; // Scale factor for specular contribution
    return (specularColor + diffuseLighting); // GGX Geometric attenuation doesn't take distance to the light into the account.

}

vec3 BounceRay(vec3 pointPosition, vec3 incomingVector, vec3 surfaceNormal, float materialToIgnore, int maxBounces)
{
    vec3 accumulatedColor = vec3(0.);
    if (materialToIgnore == MAT_PAGES)
    {
        return accumulatedColor;
    }
    // Reflection bounces
    for (int i = 0; i < maxBounces; i++)
    {

        float reflectedMaterial;
        vec3 reflectedSurfaceNormal;
        float distanceFromBounceRayToSurface = 0.;

        vec3 albedo, materialProperties;
        GetDiffuseMaterial(materialToIgnore, surfaceNormal, pointPosition, albedo, materialProperties);


        // Perturb the reflection vector by roughness for glossy reflections
        vec3 randomVec = normalize(vec3(
            fract(sin(dot(pointPosition.xy, vec2(12.9898, 78.233))) * 43758.5453),
            fract(sin(dot(pointPosition.yz, vec2(93.9898, 67.345))) * 29358.5453),
            fract(sin(dot(pointPosition.zx, vec2(15.9898, 27.345))) * 15731.5453)
        ));

        vec3 reflectedViewVector = normalize(reflect(incomingVector, surfaceNormal) + 100.*randomVec*pow(materialProperties.x, 4.));
        Scene(pointPosition, reflectedViewVector, distanceFromBounceRayToSurface, reflectedMaterial, reflectedSurfaceNormal, materialToIgnore);
        vec3 reflectedSurfacePos = pointPosition + reflectedViewVector * distanceFromBounceRayToSurface;
        vec3 lightPosition = reflectedSurfacePos;


        float Fo = materialProperties.y;
        // Fresnel-Schlick approximation for reflectivity
        float Fresnel_Schlick = Fo + (1.0 - Fo) * pow(1.0 - max(dot(-incomingVector, surfaceNormal), 0.0), 5.0);

        accumulatedColor += Fresnel_Schlick*
                        Light(pointPosition, 
                            surfaceNormal, 
                            materialToIgnore, 
                            incomingVector);

        pointPosition = reflectedSurfacePos;
        materialToIgnore = reflectedMaterial;
        surfaceNormal = reflectedSurfaceNormal;
        incomingVector = reflectedViewVector;
    }

    return accumulatedColor;
}

//https://knarkowicz.wordpress.com/2016/01/06/aces-filmic-tone-mapping-curve/
vec3 ACESFilm(vec3 x)
{
    float a = 2.51f;
    float b = 0.03f;
    float c = 2.43f;
    float d = 0.59f;
    float e = 0.14f;
    return clamp((x*(a*x + b)) / (x*(c*x + d) + e), 0.0f, 1.0f);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // === NORMALIZED DEVICE COORDINATES ===
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // === CAMERA SETUP ===
    vec3 cameraPosition = vec3(0.0, 0.5, 6.0);
    vec3 cameraForwardDir = vec3(0.0, -0.10, -1.0);

    // Apply camera rotation based on time (for animation)
    mat3 mouseRotation = MRY(1.1 + sin(iTime));
    vec3 pixelForwardDir = mouseRotation * normalize(vec3(uv * 0.2, 0.0) + cameraForwardDir);
    //cameraPosition = mouseRotation * cameraPosition;

    // === RAY MARCHING INITIALIZATION ===
    float distanceToSurface;
    vec3 surfaceNormal;
    float material;
    vec3 lightPosition = LIGHT_POS;
    fragColor = vec4(0.0);
    vec3 surfacePosition;
    for (int sampleNum = 0; sampleNum < ANTIALIASING_SAMPLES; sampleNum++)
    {

        vec3 cameraPositionLoc = mouseRotation * (cameraPosition + JITTER[sampleNum]*1./iResolution.y);
        // Perform ray marching to find the first intersection
        Scene(cameraPositionLoc, pixelForwardDir, distanceToSurface, material, surfaceNormal, 0.0);

        // === LIGHT SOURCE CHECK ===
        if (material == MAT_LIGHT) {
            fragColor = vec4(1.0);
            return;
        }

        // === SURFACE COLOR CALCULATION ===
        surfacePosition = cameraPositionLoc + pixelForwardDir * distanceToSurface;

        // === DIRECT LIGHTING & SHADOWS ===
        if (material > 0.0) {
            // Calculate vector from surface to light
            vec3 lightDirUnnormalized = lightPosition - surfacePosition;
            float expectedDistanceToLight = length(lightDirUnnormalized);
            vec3 lightDir = normalize(lightDirUnnormalized);

            // Shadow ray cast to check for occlusion
            float shadowDistance;
            float shadowMaterial;
            vec3 shadowNormal;

            Scene(surfacePosition, lightDir, shadowDistance, shadowMaterial, shadowNormal, material);

            // Compute light contribution
            vec3 lightContribution = Light(surfacePosition, surfaceNormal, material, pixelForwardDir);

            // === FAKE SOFT SHADOWS ===
            float fakeSoftShadow = min(pow(shadowDistance, 8.0), 1.0);
            fragColor.rgb += lightContribution * fakeSoftShadow;

            // === FAKE AMBIENT LIGHTING ===
            vec3 albedo, materialProperties;
            GetDiffuseMaterial(material, surfaceNormal, surfacePosition, albedo, materialProperties);
            fragColor.rgb += albedo * 0.25;  // Ambient light
        }
    }
    fragColor.rgb/=float(ANTIALIASING_SAMPLES);

    // Perform reflection bounces (5 max)
    fragColor.rgb += BounceRay(surfacePosition, pixelForwardDir, surfaceNormal, material, 5);

    // === FINAL COLOR ADJUSTMENTS ===
    fragColor.a = 1.0;
    fragColor.rgb *= 1.2;
    fragColor.rgb = ACESFilm(fragColor.rgb);  // Apply tone mapping
    fragColor.rgb = pow(fragColor.rgb, vec3(2.2));
}
